/**
 * Accordion FSM - Finite State Machine for Accordion state management
 *
 * This FSM manages which accordion items are currently expanded, supporting
 * both single-selection (one item at a time) and multiple-selection modes.
 *
 * Unlike Modal/Dropdown FSMs which track visibility states with animations,
 * the Accordion FSM focuses on managing the set of active (expanded) item keys.
 * Individual item animations are handled by CSS transitions.
 *
 * Events:
 * - TOGGLE: Toggle an item's expanded state
 * - EXPAND: Force expand an item
 * - COLLAPSE: Force collapse an item
 * - COLLAPSE_ALL: Collapse all items
 * - RESET_FROM_PROPS: Sync with controlled props
 *
 * Selection Modes:
 * - 'single': Only one item can be expanded at a time
 * - 'multiple': Multiple items can be expanded simultaneously
 */

import type { AccordionSelectionMode } from './Accordion.types';

/**
 * The Accordion FSM state object
 */
export interface AccordionFSMState {
  /**
   * Set of currently active (expanded) eventKeys
   * Using a Set for O(1) lookup and to prevent duplicates
   */
  readonly activeKeys: ReadonlySet<string>;

  /**
   * Selection mode for the accordion
   */
  readonly selectionMode: AccordionSelectionMode;
}

/**
 * Events that trigger state transitions in the Accordion FSM
 */
export type AccordionFSMEvent =
  | { readonly type: 'TOGGLE'; readonly eventKey: string }
  | { readonly type: 'EXPAND'; readonly eventKey: string }
  | { readonly type: 'COLLAPSE'; readonly eventKey: string }
  | { readonly type: 'COLLAPSE_ALL' }
  | { readonly type: 'RESET_FROM_PROPS'; readonly activeKeys: readonly string[] };

/**
 * Creates the initial FSM state
 *
 * @param activeKeys - Initially active eventKeys
 * @param selectionMode - Selection mode ('single' or 'multiple')
 * @returns The initial FSM state
 */
export function createInitialAccordionFSMState(
  activeKeys: readonly string[] = [],
  selectionMode: AccordionSelectionMode = 'single'
): AccordionFSMState {
  // In single mode, only keep the first active key
  const firstKey = activeKeys[0];
  const validKeys: string[] =
    selectionMode === 'single' && activeKeys.length > 1 && firstKey !== undefined
      ? [firstKey]
      : [...activeKeys];

  return {
    activeKeys: new Set(validKeys),
    selectionMode,
  };
}

/**
 * Pure reducer function for the Accordion FSM
 *
 * Transition Rules:
 *
 * TOGGLE (single mode):
 * - If item is expanded: collapse it (activeKeys becomes empty)
 * - If item is collapsed: expand it and collapse all others
 *
 * TOGGLE (multiple mode):
 * - If item is expanded: collapse it
 * - If item is collapsed: expand it (others stay as-is)
 *
 * EXPAND:
 * - In single mode: collapse all others, expand this one
 * - In multiple mode: add to activeKeys (if not already present)
 *
 * COLLAPSE:
 * - Remove eventKey from activeKeys
 *
 * COLLAPSE_ALL:
 * - Clear all activeKeys
 *
 * RESET_FROM_PROPS:
 * - Replace activeKeys with provided values (respecting selection mode)
 *
 * @param state - Current FSM state
 * @param event - Event triggering the transition
 * @returns New FSM state
 */
export function accordionFSMReducer(
  state: AccordionFSMState,
  event: AccordionFSMEvent
): AccordionFSMState {
  switch (event.type) {
    case 'TOGGLE': {
      const { eventKey } = event;
      const isCurrentlyActive = state.activeKeys.has(eventKey);

      if (isCurrentlyActive) {
        // Collapse this item
        const newKeys = new Set(state.activeKeys);
        newKeys.delete(eventKey);
        return { ...state, activeKeys: newKeys };
      } else {
        // Expand this item
        if (state.selectionMode === 'single') {
          // In single mode, only this item should be active
          return { ...state, activeKeys: new Set([eventKey]) };
        } else {
          // In multiple mode, add to existing active items
          const newKeys = new Set(state.activeKeys);
          newKeys.add(eventKey);
          return { ...state, activeKeys: newKeys };
        }
      }
    }

    case 'EXPAND': {
      const { eventKey } = event;

      if (state.activeKeys.has(eventKey)) {
        // Already expanded, no change needed
        return state;
      }

      if (state.selectionMode === 'single') {
        // In single mode, replace all with just this one
        return { ...state, activeKeys: new Set([eventKey]) };
      } else {
        // In multiple mode, add to existing
        const newKeys = new Set(state.activeKeys);
        newKeys.add(eventKey);
        return { ...state, activeKeys: newKeys };
      }
    }

    case 'COLLAPSE': {
      const { eventKey } = event;

      if (!state.activeKeys.has(eventKey)) {
        // Already collapsed, no change needed
        return state;
      }

      const newKeys = new Set(state.activeKeys);
      newKeys.delete(eventKey);
      return { ...state, activeKeys: newKeys };
    }

    case 'COLLAPSE_ALL': {
      if (state.activeKeys.size === 0) {
        // Already all collapsed
        return state;
      }
      return { ...state, activeKeys: new Set() };
    }

    case 'RESET_FROM_PROPS': {
      const { activeKeys } = event;

      // In single mode, only keep the first key
      const firstKey = activeKeys[0];
      const validKeys: string[] =
        state.selectionMode === 'single' && activeKeys.length > 1 && firstKey !== undefined
          ? [firstKey]
          : [...activeKeys];

      const newKeysSet = new Set<string>(validKeys);

      // Check if the sets are equal to avoid unnecessary updates
      if (
        newKeysSet.size === state.activeKeys.size &&
        [...newKeysSet].every((key) => state.activeKeys.has(key))
      ) {
        return state;
      }

      return { ...state, activeKeys: newKeysSet };
    }

    default:
      return state;
  }
}

/**
 * Get the list of active keys as an array (for callbacks and controlled mode)
 *
 * @param state - Current FSM state
 * @returns Array of active eventKeys
 */
export function getActiveKeysArray(state: AccordionFSMState): string[] {
  return [...state.activeKeys];
}

/**
 * Check if a specific item is expanded
 *
 * @param state - Current FSM state
 * @param eventKey - The eventKey to check
 * @returns Whether the item is expanded
 */
export function isItemExpanded(state: AccordionFSMState, eventKey: string): boolean {
  return state.activeKeys.has(eventKey);
}

/**
 * Get the visual state for an accordion item (for data-visual-state attribute)
 * Note: Animation states (expanding/collapsing) are managed by CSS transitions,
 * so we only report the logical state here.
 *
 * @param state - Current FSM state
 * @param eventKey - The eventKey to check
 * @returns 'expanded' or 'collapsed'
 */
export function getAccordionItemVisualState(
  state: AccordionFSMState,
  eventKey: string
): 'expanded' | 'collapsed' {
  return state.activeKeys.has(eventKey) ? 'expanded' : 'collapsed';
}

/**
 * Accordion Component
 *
 * A fully accessible accordion component following Bootstrap 5 patterns
 * with FSM-driven state management for expand/collapse behavior.
 *
 * @module Accordion
 * @see https://getbootstrap.com/docs/5.3/components/accordion/
 */

import {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useReducer,
  useRef,
} from 'react';

import { cn } from '../../utils';
import { mergeRefs } from '../../utils/dom/mergeRefs';

import {
  accordionFSMReducer,
  createInitialAccordionFSMState,
  getActiveKeysArray,
} from './Accordion.fsm';

import type {
  AccordionButtonProps,
  AccordionContextValue,
  AccordionHeaderProps,
  AccordionItemContextValue,
  AccordionItemProps,
  AccordionPanelProps,
  AccordionProps,
} from './Accordion.types';

// =============================================================================
// Contexts
// =============================================================================

/**
 * Accordion context for sharing state between components
 */
const AccordionContext = createContext<AccordionContextValue | null>(null);

/**
 * AccordionItem context for sharing item-level state
 */
const AccordionItemContext = createContext<AccordionItemContextValue | null>(null);

/**
 * Hook to access accordion context
 */
function useAccordionContext(): AccordionContextValue {
  const context = useContext(AccordionContext);
  if (!context) {
    throw new Error('Accordion components must be used within an Accordion component');
  }
  return context;
}

/**
 * Hook to access accordion item context
 */
function useAccordionItemContext(): AccordionItemContextValue {
  const context = useContext(AccordionItemContext);
  if (!context) {
    throw new Error('AccordionButton and AccordionPanel must be used within an Accordion.Item');
  }
  return context;
}

// =============================================================================
// Accordion Root Component
// =============================================================================

/**
 * Accordion Component
 *
 * A container for accordion items that manages expansion state.
 * Supports single (one at a time) or multiple (many open) selection modes.
 *
 * ACCESSIBILITY FEATURES (WCAG 2.2 AA):
 * - Semantic structure with proper heading hierarchy
 * - Keyboard navigation (Tab, Enter, Space)
 * - ARIA attributes on buttons and panels
 *
 * SECURITY FEATURES:
 * - Prop whitelisting (no unrestricted spread)
 * - Explicit event handlers only
 *
 * @example
 * ```tsx
 * <Accordion>
 *   <Accordion.Item eventKey="0">
 *     <Accordion.Button>Section 1</Accordion.Button>
 *     <Accordion.Panel>Content 1</Accordion.Panel>
 *   </Accordion.Item>
 *   <Accordion.Item eventKey="1">
 *     <Accordion.Button>Section 2</Accordion.Button>
 *     <Accordion.Panel>Content 2</Accordion.Panel>
 *   </Accordion.Item>
 * </Accordion>
 * ```
 */
const AccordionRoot = forwardRef<HTMLDivElement, AccordionProps>(
  (
    {
      children,
      selectionMode = 'single',
      activeKeys: controlledActiveKeys,
      onActiveKeysChange,
      defaultActiveKeys = [],
      flush = false,
      onItemExpand,
      onItemCollapse,
      onItemToggle,
      className = '',
      style,
      id,
      'data-testid': dataTestId,
      'data-test': dataTest,
    },
    ref
  ) => {
    // Determine if controlled
    const isControlled = controlledActiveKeys !== undefined;

    // Initialize FSM state
    const [fsmState, dispatch] = useReducer(
      accordionFSMReducer,
      { activeKeys: isControlled ? controlledActiveKeys : defaultActiveKeys, selectionMode },
      ({ activeKeys, selectionMode: mode }) => createInitialAccordionFSMState(activeKeys, mode)
    );

    // Track previous active keys for expand/collapse callbacks
    const prevActiveKeysRef = useRef<Set<string>>(new Set(fsmState.activeKeys));

    // Track button refs for arrow-key navigation
    const buttonRefsRef = useRef<Map<string, HTMLButtonElement>>(new Map());

    // Register button ref for arrow-key navigation
    const registerButtonRef = useCallback(
      (eventKey: string, buttonRef: HTMLButtonElement | null) => {
        if (buttonRef) {
          buttonRefsRef.current.set(eventKey, buttonRef);
        } else {
          buttonRefsRef.current.delete(eventKey);
        }
      },
      []
    );

    // Get button keys sorted by DOM position
    const getSortedButtonKeys = useCallback((): string[] => {
      const entries = [...buttonRefsRef.current.entries()];
      entries.sort(([, a], [, b]) => {
        const position = a.compareDocumentPosition(b);
        if (position & Node.DOCUMENT_POSITION_FOLLOWING) { return -1; }
        if (position & Node.DOCUMENT_POSITION_PRECEDING) { return 1; }
        return 0;
      });
      return entries.map(([key]) => key);
    }, []);

    // Navigate to next/previous button using arrow keys
    const navigateToButton = useCallback(
      (eventKey: string, direction: 'next' | 'prev') => {
        const order = getSortedButtonKeys();
        const currentIndex = order.indexOf(eventKey);
        if (currentIndex === -1 || order.length === 0) {
          return;
        }

        // Build a rotated list starting from next/prev position to enable wrapping
        const rotatedKeys =
          direction === 'next'
            ? [...order.slice(currentIndex + 1), ...order.slice(0, currentIndex)]
            : [
                ...order.slice(0, currentIndex).reverse(),
                ...order.slice(currentIndex + 1).reverse(),
              ];

        // Find the first focusable (non-disabled) button
        for (const key of rotatedKeys) {
          const button = buttonRefsRef.current.get(key);
          if (button && !button.disabled) {
            button.focus();
            return;
          }
        }
      },
      [getSortedButtonKeys]
    );

    // Navigate to first/last focusable button (for Home/End keys)
    const navigateToEdge = useCallback(
      (position: 'first' | 'last') => {
        const order = getSortedButtonKeys();
        if (order.length === 0) { return; }

        const keys = position === 'first' ? order : [...order].reverse();

        for (const key of keys) {
          const button = buttonRefsRef.current.get(key);
          if (button && !button.disabled) {
            button.focus();
            return;
          }
        }
      },
      [getSortedButtonKeys]
    );

    // Sync with controlled props when they change
    useEffect(() => {
      if (isControlled) {
        dispatch({ type: 'RESET_FROM_PROPS', activeKeys: controlledActiveKeys });
      }
    }, [isControlled, controlledActiveKeys]);

    // Fire expand/collapse callbacks when activeKeys change
    useEffect(() => {
      const prevKeys = prevActiveKeysRef.current;
      const currentKeys = fsmState.activeKeys;

      // Find newly expanded items
      currentKeys.forEach((key) => {
        if (!prevKeys.has(key)) {
          onItemExpand?.(key);
          onItemToggle?.(key, { expanded: true });
        }
      });

      // Find newly collapsed items
      prevKeys.forEach((key) => {
        if (!currentKeys.has(key)) {
          onItemCollapse?.(key);
          onItemToggle?.(key, { expanded: false });
        }
      });

      prevActiveKeysRef.current = new Set(currentKeys);
    }, [fsmState.activeKeys, onItemExpand, onItemCollapse, onItemToggle]);

    // Toggle item handler
    const toggleItem = useCallback(
      (eventKey: string) => {
        if (isControlled) {
          // In controlled mode, compute next state and call callback
          const wasExpanded = fsmState.activeKeys.has(eventKey);
          let newKeys: string[];

          if (wasExpanded) {
            newKeys = getActiveKeysArray(fsmState).filter((k) => k !== eventKey);
          } else {
            if (selectionMode === 'single') {
              newKeys = [eventKey];
            } else {
              newKeys = [...getActiveKeysArray(fsmState), eventKey];
            }
          }

          onActiveKeysChange?.(newKeys);
        } else {
          // In uncontrolled mode, update internal state
          dispatch({ type: 'TOGGLE', eventKey });
        }
      },
      [isControlled, fsmState, selectionMode, onActiveKeysChange]
    );

    // Memoize context value
    const contextValue = useMemo<AccordionContextValue>(
      () => ({
        activeKeys: getActiveKeysArray(fsmState),
        toggleItem,
        selectionMode,
        flush,
        registerButtonRef,
        navigateToButton,
        navigateToEdge,
      }),
      [
        fsmState,
        toggleItem,
        selectionMode,
        flush,
        registerButtonRef,
        navigateToButton,
        navigateToEdge,
      ]
    );

    // Compute classes
    const accordionClasses = useMemo(
      () => cn('accordion', flush && 'accordion-flush', className),
      [flush, className]
    );

    return (
      <AccordionContext.Provider value={contextValue}>
        <div
          ref={ref}
          id={id}
          className={accordionClasses}
          style={style}
          data-testid={dataTestId}
          data-test={dataTest}
        >
          {children}
        </div>
      </AccordionContext.Provider>
    );
  }
);

AccordionRoot.displayName = 'Accordion';

// =============================================================================
// Accordion.Item Component
// =============================================================================

/**
 * Accordion.Item Component
 *
 * Container for a single accordion section including button and panel.
 *
 * @example
 * ```tsx
 * <Accordion.Item eventKey="0">
 *   <Accordion.Button>Section Title</Accordion.Button>
 *   <Accordion.Panel>Section Content</Accordion.Panel>
 * </Accordion.Item>
 * ```
 */
const AccordionItem = forwardRef<HTMLDivElement, AccordionItemProps>(
  (
    {
      children,
      eventKey,
      disabled = false,
      className = '',
      style,
      id,
      'data-testid': dataTestId,
      'data-test': dataTest,
    },
    ref
  ) => {
    const { activeKeys } = useAccordionContext();
    const generatedId = useId();
    const itemId = id ?? `accordion-item-${generatedId}`;
    const buttonId = `${itemId}-button`;
    const panelId = `${itemId}-panel`;

    const isExpanded = activeKeys.includes(eventKey);
    const visualState = isExpanded ? 'expanded' : 'collapsed';

    // Memoize context value
    const itemContextValue = useMemo<AccordionItemContextValue>(
      () => ({
        eventKey,
        isExpanded,
        disabled,
        buttonId,
        panelId,
      }),
      [eventKey, isExpanded, disabled, buttonId, panelId]
    );

    // Compute classes
    const itemClasses = useMemo(() => cn('accordion-item', className), [className]);

    return (
      <AccordionItemContext.Provider value={itemContextValue}>
        <div
          ref={ref}
          id={itemId}
          className={itemClasses}
          style={style}
          data-testid={dataTestId}
          data-test={dataTest}
          data-visual-state={visualState}
        >
          {children}
        </div>
      </AccordionItemContext.Provider>
    );
  }
);

AccordionItem.displayName = 'Accordion.Item';

// =============================================================================
// Accordion.Button Component
// =============================================================================

/**
 * Accordion.Button Component
 *
 * The clickable button that triggers expand/collapse.
 * Renders as a semantic `<button>` element with proper ARIA attributes.
 *
 * @example
 * ```tsx
 * <Accordion.Button>Section Title</Accordion.Button>
 * ```
 */
const AccordionButton = forwardRef<HTMLButtonElement, AccordionButtonProps>(
  (
    {
      children,
      onClick,
      onKeyDown,
      className = '',
      style,
      id,
      'data-testid': dataTestId,
      'data-test': dataTest,
    },
    ref
  ) => {
    const { toggleItem, registerButtonRef, navigateToButton, navigateToEdge } =
      useAccordionContext();
    const { eventKey, isExpanded, disabled, buttonId, panelId } = useAccordionItemContext();

    // Internal ref for arrow-key navigation
    const internalRef = useRef<HTMLButtonElement>(null);

    // Stable merged ref: combines forwarded ref, internal ref, and registration callback
    const combinedRef = useCallback(
      (node: HTMLButtonElement | null) => {
        mergeRefs([
          ref,
          internalRef,
          (n: HTMLButtonElement | null) => registerButtonRef(eventKey, n),
        ])(node);
      },
      [ref, eventKey, registerButtonRef]
    );

    // Handle click
    const handleClick = useCallback(
      (event: React.MouseEvent<HTMLButtonElement>) => {
        if (disabled) {
          return;
        }
        toggleItem(eventKey);
        onClick?.(event);
      },
      [disabled, toggleItem, eventKey, onClick]
    );

    // Handle keyboard
    const handleKeyDown = useCallback(
      (event: React.KeyboardEvent<HTMLButtonElement>) => {
        if (disabled) {
          return;
        }

        // Arrow-key navigation between accordion buttons
        switch (event.key) {
          case 'ArrowDown':
            event.preventDefault();
            navigateToButton(eventKey, 'next');
            break;
          case 'ArrowUp':
            event.preventDefault();
            navigateToButton(eventKey, 'prev');
            break;
          case 'Home':
            event.preventDefault();
            navigateToEdge('first');
            break;
          case 'End':
            event.preventDefault();
            navigateToEdge('last');
            break;
        }

        // Enter and Space are handled natively by button
        onKeyDown?.(event);
      },
      [disabled, onKeyDown, navigateToButton, navigateToEdge, eventKey]
    );

    // Compute classes
    const buttonClasses = useMemo(
      () => cn('accordion-button', !isExpanded && 'collapsed', className),
      [isExpanded, className]
    );

    return (
      <button
        ref={combinedRef}
        type="button"
        id={id ?? buttonId}
        className={buttonClasses}
        style={style}
        aria-expanded={isExpanded}
        aria-controls={panelId}
        disabled={disabled}
        aria-disabled={disabled ? 'true' : undefined}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        data-testid={dataTestId}
        data-test={dataTest}
      >
        {children}
      </button>
    );
  }
);

AccordionButton.displayName = 'Accordion.Button';

// =============================================================================
// Accordion.Panel Component
// =============================================================================

/**
 * Accordion.Panel Component
 *
 * The collapsible content panel of an accordion item.
 * Uses CSS transitions for smooth expand/collapse animations.
 *
 * @example
 * ```tsx
 * <Accordion.Panel>
 *   <p>This content will be shown when expanded.</p>
 * </Accordion.Panel>
 * ```
 */
const AccordionPanel = forwardRef<HTMLDivElement, AccordionPanelProps>(
  (
    { children, className = '', style, id, 'data-testid': dataTestId, 'data-test': dataTest },
    ref
  ) => {
    const { isExpanded, buttonId, panelId } = useAccordionItemContext();

    // Compute collapse classes based on current expansion state
    // Bootstrap CSS handles the collapse animation
    const collapseClasses = useMemo(
      () => cn('accordion-collapse', 'collapse', isExpanded && 'show', className),
      [isExpanded, className]
    );

    return (
      <section
        ref={ref}
        id={id ?? panelId}
        className={collapseClasses}
        style={style}
        aria-labelledby={buttonId}
        data-testid={dataTestId}
        data-test={dataTest}
      >
        <div className="accordion-body">{children}</div>
      </section>
    );
  }
);

AccordionPanel.displayName = 'Accordion.Panel';

// =============================================================================
// Accordion.Header Component
// =============================================================================

/**
 * Accordion.Header Component
 *
 * An optional heading wrapper for Accordion.Button that provides
 * proper semantic heading structure per WAI-ARIA Accordion Pattern.
 *
 * @example
 * ```tsx
 * <Accordion.Item eventKey="0">
 *   <Accordion.Header as="h3">
 *     <Accordion.Button>Section Title</Accordion.Button>
 *   </Accordion.Header>
 *   <Accordion.Panel>Content</Accordion.Panel>
 * </Accordion.Item>
 * ```
 */
const AccordionHeader = forwardRef<HTMLHeadingElement, AccordionHeaderProps>(
  (
    {
      children,
      as: Component = 'h2',
      className = '',
      style,
      id,
      'data-testid': dataTestId,
      'data-test': dataTest,
    },
    ref
  ) => {
    const headerClasses = useMemo(() => cn('accordion-header', className), [className]);

    return (
      <Component
        ref={ref}
        id={id}
        className={headerClasses}
        style={style}
        data-testid={dataTestId}
        data-test={dataTest}
      >
        {children}
      </Component>
    );
  }
);

AccordionHeader.displayName = 'Accordion.Header';

// =============================================================================
// Compound Component Export
// =============================================================================

/**
 * Accordion compound component with subcomponents
 */
export const Accordion = Object.assign(AccordionRoot, {
  Item: AccordionItem,
  Header: AccordionHeader,
  Button: AccordionButton,
  Panel: AccordionPanel,
});

export type { AccordionFSMEvent, AccordionFSMState } from './Accordion.fsm';

// Re-export FSM utilities
export {
  accordionFSMReducer,
  createInitialAccordionFSMState,
  getAccordionItemVisualState,
  getActiveKeysArray,
  isItemExpanded,
} from './Accordion.fsm';
// Re-export types
export type {
  AccordionButtonProps,
  AccordionContextValue,
  AccordionHeaderProps,
  AccordionItemContextValue,
  AccordionItemProps,
  AccordionItemVisualState,
  AccordionPanelProps,
  AccordionProps,
  AccordionSelectionMode,
} from './Accordion.types';

import type { SafeHTMLAttributes } from '../../types';
import type { ElementType, KeyboardEvent, MouseEvent, ReactNode } from 'react';

/**
 * Accordion selection mode
 * - 'single': Only one item can be expanded at a time (default Bootstrap behavior)
 * - 'multiple': Multiple items can be expanded simultaneously ("Always open" in Bootstrap)
 */
export type AccordionSelectionMode = 'single' | 'multiple';

/**
 * Accordion flush variant
 * - false: Default accordion with borders and rounded corners
 * - true: Flush accordion that renders edge-to-edge with parent container
 */
export type AccordionFlush = boolean;

/**
 * Safe HTML attributes that can be spread onto accordion elements
 * SECURITY: This whitelist prevents injection of dangerous attributes or event handlers
 * @see SafeHTMLAttributes
 */
export type SafeAccordionHTMLAttributes = SafeHTMLAttributes<HTMLDivElement>;

/**
 * Accordion component props
 *
 * The main container component that manages accordion state and coordinates
 * item expansion/collapse behavior.
 *
 * ACCESSIBILITY FEATURES (WCAG 2.2 AA):
 * - Each accordion button is a `<button>` element
 * - aria-expanded on buttons indicates current state
 * - aria-controls links button to its panel
 * - Panel has role="region" and aria-labelledby
 * - Keyboard navigation (Tab, Enter, Space)
 *
 * SECURITY FEATURES:
 * - Prop whitelisting (no unrestricted spread)
 * - Explicit event handlers only
 *
 * @example
 * ```tsx
 * // Basic accordion (single mode - one at a time)
